select jsonb_build_object('syntheticAgentRuns',(select count(*) from public.agent_runs where config->>'validationNamespace' like '12f9b:%'),'syntheticAttempts',(select count(*) from public.pipeline_event_attempts where event_key like '12f9b:%'),'syntheticReservations',(select count(*) from public.agent_logs where payload->>'eventKey' like '12f9b:%' or payload->>'validationNamespace' like '12f9b:%')) as migration36_residuals;
